import{_ as a,a0 as r,w as p,s as d,I as t,x as n,a1 as e,A as o,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const E=JSON.parse('{"title":"在 Linux 上运行你最喜欢的 Windows 应用程序 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上运行你最喜欢的 Windows 应用程序 | LCTT (202103) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上运行你最喜欢的 Windows 应用程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上运行你最喜欢的 Windows 应用程序 | LCTT (202103) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202103/20210220 Run your favorite Windows applications on Linux","title":"在 Linux 上运行你最喜欢的 Windows 应用程序","tag":"202103","desc":""},"relativePath":"202103/20210220 Run your favorite Windows applications on Linux.md","filePath":"[post].md"}'),u={name:"202103/20210220 Run your favorite Windows applications on Linux.md"};function w(W,i,f,m,x,g){const s=r("Link");return p(),d("div",null,[i[27]||(i[27]=t("h1",{id:"在-linux-上运行你最喜欢的-windows-应用程序",tabindex:"-1"},[n("在 Linux 上运行你最喜欢的 Windows 应用程序 "),t("a",{class:"header-anchor",href:"#在-linux-上运行你最喜欢的-windows-应用程序","aria-label":"Permalink to “在 Linux 上运行你最喜欢的 Windows 应用程序”"},"​")],-1)),i[28]||(i[28]=t("blockquote",null,[t("p",null,"WINE 是一个开源项目，它可以协助很多 Windows 应用程序在 Linux 上运行，就好像它们是原生程序一样。")],-1)),i[29]||(i[29]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202103/07/231159kwsn2snlilwbs9ns.jpg",alt:""})],-1)),i[30]||(i[30]=t("p",null,"在 2021 年，有很多比以往更喜欢 Linux 的原因。在这系列中，我将分享使用 Linux 的 21 种原因。这里是如何使用 WINE 来实现从 Windows 到 Linux 的无缝切换。",-1)),i[31]||(i[31]=t("p",null,"你有只能在 Windows 上运行的应用程序吗？那一个应用程序阻碍你切换到 Linux 的唯一因素吗？如果是这样的话，你将会很高兴知道 WINE，这是一个开源项目，它几乎重新发明了关键的 Windows 库，使为 Windows 编译的应用程序可以在 Linux 上运行。",-1)),t("p",null,[i[1]||(i[1]=n("WINE 代表着“Wine Is Not an Emulator” ，它指的是驱动这项技术的代码。开源开发者从 1993 年就开始致力将应用程序的任何传入 Windows API 调用翻译为 ",-1)),e(s,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:o(()=>[...i[0]||(i[0]=[n("POSIX",-1)])]),_:1}),i[2]||(i[2]=n(" 调用。",-1))]),t("p",null,[i[6]||(i[6]=n("这是一个令人十分惊讶的编程壮举，尤其是考虑到这个项目是独立运行的，没有来自微软的帮助（至少可以这样说），但是也有局限性。一个应用程序偏离 Windows API 的 “内核” 越远，WINE 就越不能预期应用程序的请求。有一些供应商可以弥补这一点，尤其是 ",-1)),e(s,{href:"https://www.codeweavers.com/crossover"},{default:o(()=>[...i[3]||(i[3]=[n("Codeweavers",-1)])]),_:1}),i[7]||(i[7]=n(" 和 ",-1)),e(s,{href:"https://github.com/ValveSoftware/Proton"},{default:o(()=>[...i[4]||(i[4]=[n("Valve Software",-1)])]),_:1}),i[8]||(i[8]=n("。在需要翻译应用程序的制作者和翻译的人们及公司之间没有协调配合，因此，比如说一个更新的软件作品和从 ",-1)),e(s,{href:"http://winehq.org"},{default:o(()=>[...i[5]||(i[5]=[n("WINE 总部",-1)])]),_:1}),i[9]||(i[9]=n(" 获得完美适配状态之间可能会有一些时间上的滞后。",-1))]),i[32]||(i[32]=l('<p>然而，如果你想在 Linux 上运行一个著名的 Windows 应用程序，WINE 可能已经为它准备好了可能性。</p><h3 id="安装-wine" tabindex="-1">安装 WINE <a class="header-anchor" href="#安装-wine" aria-label="Permalink to “安装 WINE”">​</a></h3><p>你可以从你的 Linux 发行版的软件包存储库中安装 WINE 。在 Fedora、CentOS Stream 或 RHEL 系统上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install wine</span></span></code></pre></div><p>在 Debian、Linux Mint、Elementary 及相似的系统上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install wine</span></span></code></pre></div><p>WINE 不是一个你自己启动的应用程序。当启动一个 Windows 应用程序时，它是一个被调用的后端。你与 WINE 的第一次交互很可能就发生在你启动一个 Windows 应用程序的安装程序时。</p><h3 id="安装一个应用程序" tabindex="-1">安装一个应用程序 <a class="header-anchor" href="#安装一个应用程序" aria-label="Permalink to “安装一个应用程序”">​</a></h3>',8)),t("p",null,[e(s,{href:"https://sourceforge.net/projects/tinycad/"},{default:o(()=>[...i[10]||(i[10]=[n("TinyCAD",-1)])]),_:1}),i[11]||(i[11]=n(" 是一个极好的用于设计电路的开源应用程序，但是它仅在 Windows 上可用。虽然它是一个小型的应用程序，但是它确实包含一些 .NET 组件，因此应该能对 WINE 进行一些压力测试。",-1))]),i[33]||(i[33]=l('<p>首先，下载 TinyCAD 的安装程序。Windows 安装程序通常都是这样，它是一个 <code>.exe</code> 文件。在下载后，双击文件来启动它。</p><p><img src="https://opensource.com/sites/default/files/wine-tinycad-install.jpg" alt="WINE TinyCAD 安装向导"></p><p><em>TinyCAD 的 WINE 安装向导</em></p><p>像你在 Windows 上一样逐步完成安装程序。通常最好接受默认选项，尤其是与 WINE 有关的地方。WINE 环境基本上是独立的，隐藏在你的硬盘驱动器上的一个 <code>drive_c</code> 目录中，作为 Windows 应用程序使用的一个文件系统的仿真根目录。</p><p><img src="https://opensource.com/sites/default/files/wine-tinycad-drive_0.jpg" alt="WINE TinyCAD 安装和目标驱动器"></p><p><em>WINE TinyCAD 目标驱动器</em></p><p>安装完成后，应用程序通常会为你提供启动机会。如果你正准备测试一下它的话，启动应用程序。</p><h3 id="启动-windows-应用程序" tabindex="-1">启动 Windows 应用程序 <a class="header-anchor" href="#启动-windows-应用程序" aria-label="Permalink to “启动 Windows 应用程序”">​</a></h3><p>除了在安装后的第一次启动外，在正常情况下，你启动一个 WINE 应用程序的方式与你启动一个本地 Linux 应用程序相同。不管你使用应用程序菜单、活动屏幕或者只是在运行器中输入应用程序的名称，在 WINE 中运行的桌面 Windows 应用程序都会被视为在 Linux 上的本地应用程序。</p><p><img src="https://opensource.com/sites/default/files/wine-tinycad-running.jpg" alt="TinyCAD 使用 WINE 运行"></p><p><em>通过 WINE 的支持来运行 TinyCAD</em></p><h3 id="当-wine-失败时" tabindex="-1">当 WINE 失败时 <a class="header-anchor" href="#当-wine-失败时" aria-label="Permalink to “当 WINE 失败时”">​</a></h3><p>我在 WINE 中的大多数应用程序，包括 TinyCAD ，都能如期运行。不过，也会有例外。在这些情况下，你可以等几个月来查看 WINE 开发者 （或者，如果是一款游戏，就等候 Valve Software）是否进行追加修补，或者你可以联系一个像 Codeweavers 这样的供应商来查看他们是否出售对你所需要的应用程序的服务支持。</p><h3 id="wine-是种欺骗-但它用于正道" tabindex="-1">WINE 是种欺骗，但它用于正道 <a class="header-anchor" href="#wine-是种欺骗-但它用于正道" aria-label="Permalink to “WINE 是种欺骗，但它用于正道”">​</a></h3><p>一些 Linux 用户觉得：如果你使用 WINE 的话，你就是在“欺骗” Linux。它可能会让人有这种感觉，但是 WINE 是一个开源项目，它使用户能够切换到 Linux ，并且仍然能够运行工作或爱好所需的应用程序。如果 WINE 解决了你的问题，让你使用 Linux，那就使用它，并拥抱 Linux 的灵活性。</p><hr>',16)),t("p",null,[i[13]||(i[13]=n("via: ",-1)),e(s,{href:"https://opensource.com/article/21/2/linux-wine"},{default:o(()=>[...i[12]||(i[12]=[n("https://opensource.com/article/21/2/linux-wine",-1)])]),_:1})]),t("p",null,[i[18]||(i[18]=n("作者：",-1)),e(s,{href:"https://opensource.com/users/seth"},{default:o(()=>[...i[14]||(i[14]=[n("Seth Kenlon",-1)])]),_:1}),i[19]||(i[19]=n(" 选题：",-1)),e(s,{href:"https://github.com/lujun9972"},{default:o(()=>[...i[15]||(i[15]=[n("lujun9972",-1)])]),_:1}),i[20]||(i[20]=n(" 译者：",-1)),e(s,{href:"https://github.com/robsean"},{default:o(()=>[...i[16]||(i[16]=[n("robsean",-1)])]),_:1}),i[21]||(i[21]=n(" 校对：",-1)),e(s,{href:"https://github.com/wxy"},{default:o(()=>[...i[17]||(i[17]=[n("wxy",-1)])]),_:1})]),t("p",null,[i[24]||(i[24]=n("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...i[22]||(i[22]=[n("LCTT",-1)])]),_:1}),i[25]||(i[25]=n(" 原创编译，",-1)),e(s,{href:"https://linux.cn/"},{default:o(()=>[...i[23]||(i[23]=[n("Linux中国",-1)])]),_:1}),i[26]||(i[26]=n(" 荣誉推出",-1))])])}const T=a(u,[["render",w]]);export{E as __pageData,T as default};
